{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "San Francisco algorithmic rent and occupancy setting ban",
      "requirement": "Landlords are prohibited from using algorithmic devices or revenue management software that rely on non-public competitor data to set or advise on rents or occupancy levels. It is also unlawful to sell, license, or provide such devices to San Francisco landlords.",
      "requirement_es": "Se prohíbe a los propietarios utilizar dispositivos algorítmicos o programas de gestión de ingresos basados en datos no públicos de competidores para fijar o recibir recomendaciones sobre alquileres o niveles de ocupación. También es ilegal vender, licenciar o proporcionar tales herramientas a propietarios en San Francisco.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Aggregated rental data reports that do not recommend rents or occupancy levels for future leases",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Products used to establish rent or income limits in accordance with affordable housing program guidelines",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "product used for the purpose of establishing rent or income limits in accordance with the affordable housing program guidelines"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-10-14",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties of up to $1,000 per violation, plus injunctive relief, restitution/return of illegal profits, damages, and attorney's fees and costs",
      "source_citation": "S.F. Admin. Code § 37.10C",
      "quote": {
        "chunk": "c347",
        "start_words": "It shall be unlawful for a landlord",
        "end_words": "residential dwelling units in San Francisco."
      },
      "confidence": 0.98
    }
  ]
}
